1	//! Validated Qwen3.5 model config.
2	//!
3	//! This module owns the *model* geometry: deserialized-from-disk [`RawConfig`]
4	//! is converted once into a validated [`Config35`] via [`TryFrom`]. It has no
5	//! knowledge of tensor parallelism — sharded/local dimensions, shard ranges and
6	//! the TP assignment live in [`super::tp`] as a separate directional boundary.
7	
8	use std::fs;
9	
10	use anyhow::Result;
11	use serde::Deserialize;
12	
13	use super::error::ConfigError;
14	
15	/// Which attention variant a layer uses. Model-level (TP-agnostic) layout.
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub(crate) enum LayerType {
18	    FullAttention,
19	    LinearAttention,
20	}
21	
22	/// RoPE block inside `text_config`. Only these two keys are read.
23	#[derive(Debug, Deserialize)]
24	struct RopeParameters {
25	    rope_theta: f64,
26	    partial_rotary_factor: f64,
27	}
28	
29	/// Raw `text_config` block, exactly as it appears on disk.
30	#[derive(Debug, Deserialize)]
31	pub(crate) struct TextConfig {
32	    hidden_size: usize,
33	    intermediate_size: usize,
34	    num_hidden_layers: usize,
35	    num_attention_heads: usize,
36	    num_key_value_heads: usize,
37	    head_dim: usize,
38	    vocab_size: usize,
39	    rms_norm_eps: f64,
40	    layer_types: Vec<String>,
41	    linear_conv_kernel_dim: usize,
42	    linear_key_head_dim: usize,
43	    linear_num_key_heads: usize,
44	    linear_num_value_heads: usize,
45	    linear_value_head_dim: usize,
46	    rope_parameters: RopeParameters,
47	    max_position_embeddings: Option<usize>,
48	    tie_word_embeddings: Option<bool>,
49	}
50	
51	/// Raw Qwen3.5 config as deserialized from `config.json`. Held only long enough
52	/// to be validated into a [`Config35`].
53	#[derive(Debug, Deserialize)]
54	pub(crate) struct RawConfig {
55	    text_config: TextConfig,
56	    max_position_embeddings: Option<usize>,
57	    tie_word_embeddings: Option<bool>,
58	}
59	
60	/// Head dims baked into the kernels; head counts are runtime parameters. They
61	/// are owned by the Qwen3.5 wrappers in `pegainfer_kernels::ops`, which the
62	/// Qwen3.8-Flash-Next line will drive with the same numbers once it has a device
63	/// path, so this module only re-exports them: a config that passes here is one
64	/// the kernels can run.
65	pub(crate) use pegainfer_kernels::ops::GDN_AOT_KEY_HEAD_DIM;
66	pub(crate) use pegainfer_kernels::ops::GDN_AOT_VALUE_HEAD_DIM;
67	pub(crate) use pegainfer_kernels::ops::LINEAR_CONV_MAX_KERNEL_DIM;
68	const FULL_ATTN_HEAD_DIM: usize = 256;
69	
70	/// Validated Qwen3.5 model configuration (text-only).
71	///
72	/// Every cross-field and kernel-AOT rule is enforced here, at the single
73	/// [`Self::try_from`]/[`Self::from_file`] boundary, so downstream code can only
74	/// observe a model that is known to be loadable. Tensor-parallel sharding is
75	/// never a property of this type.
76	#[derive(Debug)]
77	pub(crate) struct Config35 {
78	    // Common
79	    pub(crate) hidden_size: usize,
80	    pub(crate) intermediate_size: usize,
81	    pub(crate) num_hidden_layers: usize,
82	    pub(crate) vocab_size: usize,
83	    pub(crate) rms_norm_eps: f32,
84	    /// The checkpoint's EOS set, resolved in [`Config35::from_file`].
85	    pub(crate) eos_token_ids: Vec<u32>,
86	
87	    // Full attention params
88	    pub(crate) num_attention_heads: usize,
89	    pub(crate) num_key_value_heads: usize,
90	    pub(crate) head_dim: usize,
91	
92	    // Linear attention params
93	    pub(crate) linear_num_key_heads: usize,
94	    pub(crate) linear_key_head_dim: usize,
95	    pub(crate) linear_num_value_heads: usize,
96	    pub(crate) linear_value_head_dim: usize,
97	    pub(crate) linear_conv_kernel_dim: usize,
98	
99	    // RoPE
100	    pub(crate) rope_theta: f32,
101	    pub(crate) rotary_dim: usize,
102	    pub(crate) max_position_embeddings: usize,
103	
104	    // Layer layout
105	    pub(crate) layer_types: Vec<LayerType>,
106	
107	    /// `false` requires a top-level `lm_head.weight`; `true` reuses `embed_tokens`.
108	    pub(crate) tie_word_embeddings: bool,
109	
110	    /// Token-selection width: `vocab_size` bounded to the frontend-decodable
111	    /// vocab, then rounded up to the logits GEMM's tile multiple. Buffers and
112	    /// the sampler arena span this width.
113	    pub(crate) selection_vocab: usize,
114	    /// Tokenizer-decodable width: the rows past it are suppressed to -inf and
115	    /// are what the argmax-vs-sample routing is measured against.
116	    pub(crate) decodable_vocab: usize,
117	}
118	
119	impl Config35 {
120	    /// Load and validate `config.json` from a model directory.
121	    pub(crate) fn from_file(model_path: &str) -> Result<Self> {
122	        let config_path = format!("{}/config.json", model_path);
123	        let content = fs::read_to_string(&config_path)?;
124	        let raw: RawConfig = serde_json::from_str(&content)?;
125	        let mut config = Self::try_from(raw)?;
126	        config.eos_token_ids = pegainfer_core::eos::eos_token_ids(model_path, config.vocab_size)?;
127	        Ok(config)
128	    }
129	
130	    /// Number of full attention layers in the model.
131	    pub(crate) fn num_full_attention_layers(&self) -> usize {
132	        self.layer_types
133	            .iter()
134	            .filter(|&&t| t == LayerType::FullAttention)
135	            .count()
136	    }
137	
138	    /// Q dimension for full attention (without gate).
139	    pub(crate) fn full_attn_q_dim(&self) -> usize {
140	        self.num_attention_heads * self.head_dim
141	    }
142	
143	    /// KV dimension for full attention.
144	    pub(crate) fn full_attn_kv_dim(&self) -> usize {
145	        self.num_key_value_heads * self.head_dim
146	    }
147	
148	    pub(crate) fn decode_group_is_compiled(&self) -> bool {
149	        // Uncompiled GQA groups use the batched hybrid eager fallback.
150	        pegainfer_core::ops::SUPPORTED_GQA_GROUP_SIZES
151	            .contains(&(self.num_attention_heads / self.num_key_value_heads))
152	    }
153	
154	    /// Z projection output dimension for linear attention.
155	    pub(crate) fn linear_attn_z_dim(&self) -> usize {
156	        self.linear_num_value_heads * self.linear_value_head_dim
157	    }
158	
159	    /// Bound the output-selection width to the frontend-decodable vocab, which
160	    /// also records the semantic width the argmax-vs-sample routing uses.
161	    ///
162	    /// The frontend decodes a dense prefix of the vocab; the checkpoint may pad
163	    /// beyond it. Refusing a tokenizer wider than the checkpoint is the
164	    /// fail-closed rule, and it is checked here at the validation boundary
165	    /// rather than scattered through the loader.
166	    pub(crate) fn bound_selection_vocab(
167	        &mut self,
168	        effective_vocab: usize,
169	    ) -> Result<(), ConfigError> {
170	        if effective_vocab > self.vocab_size {
171	            return Err(ConfigError::EffectiveVocabExceedsCheckpoint {
172	                used: effective_vocab,
173	                vocab_size: self.vocab_size,
174	            });
175	        }
176	        self.decodable_vocab = effective_vocab;
177	        self.selection_vocab =
178	            pegainfer_core::decodable_vocab::aligned_logits_rows(effective_vocab, self.vocab_size);
179	        Ok(())
180	    }
181	}
182	
183	/// Validate a raw Qwen3.5 config into a [`Config35`].
184	///
185	/// Every check here is a static, load-time invariant: an invalid model file is
186	/// rejected before any weight is mapped or any CUDA buffer is allocated. The
187	/// kernel head dims are compile-time AOT constants, so a config that disagrees
188	/// cannot be served and is rejected here rather than at first kernel launch.
189	impl TryFrom<RawConfig> for Config35 {
190	    type Error = ConfigError;
191	
192	    fn try_from(raw: RawConfig) -> std::result::Result<Self, Self::Error> {
193	        let root_max_position_embeddings = raw.max_position_embeddings;
194	        let root_tie_word_embeddings = raw.tie_word_embeddings;
195	        let t = raw.text_config;
196	
197	        let tie_word_embeddings = t
198	            .tie_word_embeddings
199	            .or(root_tie_word_embeddings)
200	            .ok_or(ConfigError::MissingTieWordEmbeddings)?;
201	
202	        let layer_types: Vec<LayerType> = t
203	            .layer_types
204	            .iter()
205	            .map(|s| match s.as_str() {
206	                "full_attention" => Ok(LayerType::FullAttention),
207	                "linear_attention" => Ok(LayerType::LinearAttention),
208	                other => Err(ConfigError::UnknownLayerType(other.to_string())),
209	            })
210	            .collect::<std::result::Result<_, _>>()?;
211	
212	        if layer_types.len() != t.num_hidden_layers {
213	            return Err(ConfigError::LayerTypeCountMismatch {
214	                actual: layer_types.len(),
215	                expected: t.num_hidden_layers,
216	            });
217	        }
218	
219	        let rotary_dim = (t.head_dim as f64 * t.rope_parameters.partial_rotary_factor) as usize;
220	        if rotary_dim == 0 {
221	            return Err(ConfigError::ZeroRotaryDim);
222	        }
223	
224	        let max_position_embeddings = t
225	            .max_position_embeddings
226	            .or(root_max_position_embeddings)
227	            .ok_or(ConfigError::MissingMaxPositionEmbeddings)?;
228	        if max_position_embeddings == 0 {
229	            return Err(ConfigError::NonPositiveMaxPositionEmbeddings);
230	        }
231	
232	        if t.linear_key_head_dim != GDN_AOT_KEY_HEAD_DIM
233	            || t.linear_value_head_dim != GDN_AOT_VALUE_HEAD_DIM
234	        {
235	            return Err(ConfigError::GdnAotHeadDimMismatch {
236	                key: t.linear_key_head_dim,
237	                value: t.linear_value_head_dim,
238	                expected_key: GDN_AOT_KEY_HEAD_DIM,
239	                expected_value: GDN_AOT_VALUE_HEAD_DIM,
240	            });
241	        }
242	        if t.head_dim != FULL_ATTN_HEAD_DIM {
243	            return Err(ConfigError::FullAttnHeadDimMismatch {
244	                expected: FULL_ATTN_HEAD_DIM,
245	                actual: t.head_dim,
246	            });
247	        }
248	        if !(1..=LINEAR_CONV_MAX_KERNEL_DIM).contains(&t.linear_conv_kernel_dim) {
249	            return Err(ConfigError::LinearConvKernelDim {
250	                max: LINEAR_CONV_MAX_KERNEL_DIM,
251	                actual: t.linear_conv_kernel_dim,
252	            });
253	        }
254	        if t.linear_num_key_heads == 0
255	            || !t
256	                .linear_num_value_heads
257	                .is_multiple_of(t.linear_num_key_heads)
258	        {
259	            return Err(ConfigError::LinearHeadDivisibility {
260	                key_heads: t.linear_num_key_heads,
261	                value_heads: t.linear_num_value_heads,
262	            });
263	        }
264	        if t.num_key_value_heads == 0
265	            || !t.num_attention_heads.is_multiple_of(t.num_key_value_heads)
266	        {
267	            return Err(ConfigError::AttentionHeadDivisibility {
268	                attention_heads: t.num_attention_heads,
269	                key_value_heads: t.num_key_value_heads,
270	            });
271	        }
272	
273	        Ok(Self {
274	            hidden_size: t.hidden_size,
275	            intermediate_size: t.intermediate_size,
276	            num_hidden_layers: t.num_hidden_layers,
277	            vocab_size: t.vocab_size,
278	            rms_norm_eps: t.rms_norm_eps as f32,
279	            eos_token_ids: Vec::new(),
280	            num_attention_heads: t.num_attention_heads,
281	            num_key_value_heads: t.num_key_value_heads,
282	            head_dim: t.head_dim,
283	            linear_num_key_heads: t.linear_num_key_heads,
284	            linear_key_head_dim: t.linear_key_head_dim,
285	            linear_num_value_heads: t.linear_num_value_heads,
286	            linear_value_head_dim: t.linear_value_head_dim,
287	            linear_conv_kernel_dim: t.linear_conv_kernel_dim,
288	            rope_theta: t.rope_parameters.rope_theta as f32,
289	            rotary_dim,
290	            max_position_embeddings,
291	            layer_types,
292	            tie_word_embeddings,
293	            selection_vocab: t.vocab_size,
294	            decodable_vocab: t.vocab_size,
295	        })
296	    }
297	}
298	
299	#[cfg(test)]
300	mod tests {
301	    use super::*;
302	
303	    const VALID_RAW: &str = r#"{
304	  "max_position_embeddings": 4096,
305	  "tie_word_embeddings": true,
306	  "text_config": {
307	    "hidden_size": 512,
308	    "intermediate_size": 1024,
309	    "num_hidden_layers": 2,
310	    "num_attention_heads": 4,
311	    "num_key_value_heads": 2,
312	    "head_dim": 256,
313	    "vocab_size": 1000,
314	    "rms_norm_eps": 1e-6,
315	    "layer_types": ["linear_attention", "full_attention"],
316	    "linear_conv_kernel_dim": 4,
317	    "linear_key_head_dim": 128,
318	    "linear_num_key_heads": 16,
319	    "linear_num_value_heads": 48,
320	    "linear_value_head_dim": 128,
321	    "rope_parameters": { "rope_theta": 10000.0, "partial_rotary_factor": 0.25 },
322	    "eos_token_id": 0
323	  }
324	}"#;
325	
326	    fn parse(raw: &str) -> RawConfig {
327	        serde_json::from_str(raw).expect("fixture must deserialize")
328	    }
